def decodeSmiley(text):
	text = text.replace('&#x1F975;', '')
	text = text.replace('&#x1F351;', '')
	text = text.replace('&#x1F32E;&#xFE0F;', '')
	text = text.replace('&#x1F44C;?', '')
	text = text.replace('&#x1F44C;', '')
	text = text.replace('&#x1F346;', '')
	text = text.replace('&#x00E9;', 'é')
	text = text.replace(' &mdash; ', '')
	text = text.replace('&#x1F61C;', '')
	text = text.replace('&#x1F32D;', '')
	return text


